            state: Arc::new((
                Mutex::new(State {
                    queue: VecDeque::new(),
                    capacity,
                    closed: false,
                    cancelled: false,
                    senders_waiting: 0,
                    receivers_waiting: 0,
                }),
                Condvar::new(),
            )),
        }
    }

